import sys

def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 2:
        return
    typ = data[0].strip().lower()
    try:
        base = float(data[1])
    except:
        base = 0.0

    mapping = {
        'life': ('Life Insurance', 0.10),
        'health': ('Health Insurance', 0.20),
        'car': ('Car Insurance', 0.30)
    }

    name, perc = mapping.get(typ, ('Unknown Insurance', 0.0))
    premium = base * (1 + perc)

    print(f'Insurance Type: {name}')
    print(f'Premium: {premium}')

if __name__ == "__main__":
    main()
